INSERT INTO character_library (
  character_name, character_profile, voice_tone, personality_traits,
  visual_description, reference_image_url, generation_seed, generation_count, source
) VALUES
('결이', '프리미엄 컬렉터블 피규어/키링 캐릭터. 밝은 파랑(#00AEEF) 정육면체 몸에 은은한 크리스탈 광택 무늬, 파란 모자 또는 뾰족한 소금결정 머리, 2등신, 큰 눈에 어두운 푸른색 동공, 큰 웃음, 빨간 물방울 귀, 분홍 볼터치. 가슴 중앙에 분홍 육각형 소금결정 브로치.', '도전적, 에너지 넘침, 순수함, 희망, 새로운 시작', ARRAY['당찬 소년', '에너지 넘침', '순수함', '희망', '새로운 시작'],
 '프리미엄 비닐/레진 3D 렌더, 밝은 파랑(#00AEEF) 정육면체 몸, 크리스탈 광택 무늬, 파란 모자/소금결정 머리, 2등신(머리 60%+), 큰 눈(어두운 푸른 동공+흰 하이라이트), 큰 웃음, 빨간 물방울 귀, 분홍 볼터치, 분홍 육각형 브로치(FFB6C1). 파도/구름/별빛 제주 배경.', '/docs/character-concept-sketches/gyeol-i.svg', '결이-001', 0, 'default'),

('한라', '프리미엄 컬렉터블 피규어/키링 캐릭터. 어두운 파랑(#1A3A52) 둥근 산 모양 몸에 거친 화산암 질감, 흰/회색 긴 머리, 목걸이 또는 스카프, 이마에 경험의 주름, 분홍 볼터치. 가슴 중앙에 하늘색 육각형 소금결정 브로치.', '웅장함, 안정성, 신비로움, 제주의 근원', ARRAY['신비로운 지혜자', '웅장함', '안정성', '신비로움', '제주의 근원'],
 '프리미엄 비닐/레진 3D 렌더, 어두운 파랑(#1A3A52) 둥근 산 모양 몸, 거친 화산암 질감, 흰/회색 긴 웨이브 머리(한라산 눈 덮인 능선 연상), 하늘색 리본 클립, 큰 눈(지혜로운 표정), 포근한 미소, 분홍 볼터치, 하늘색 육각형 브로치(7FA8C9). 파도/구름/별빛 제주 배경.', '/docs/character-concept-sketches/halla.svg', '한라-002', 0, 'default'),

('용암이', '프리미엄 컬렉터블 피규어/키링 캐릭터. 진한 파랑(#0D1B2A) 둥근 몸+각진 어깨에 거친 화산암 질감, 검정 짧고 단정한 머리, 목에 짙은 색 스카프 또는 앞치마, 따뜻한 갈색 눈, 부드러운 미소, 굵고 튼튼한 팔다리, 분홍 볼터치. 가슴 중앙에 크림색 육각형 소금결정 브로치.', '신뢰감, 보호본능, 따뜻함, 기술, 성숙함', ARRAY['든든한 아버지', '용암 정령', '신뢰감', '보호본능', '따뜻함'],
 '프리미엄 비닐/레진 3D 렌더, 진한 파랑(#0D1B2A) 둥근 몸+각진 어깨, 거친 화산암 균열/용암 흐름 무늬, 짧고 단정한 어두운 회색 머리(흰머리 없음), 짙은 색 스카프 매듭, 큰 따듯한 갈색 눈(신뢰감 있는 표정), 아버지다운 미소, 크림색 육각형 브로치(F5E6D3). 파도/구름/별빛 제주 배경.', '/docs/character-concept-sketches/yong-am-i.svg', '용암이-003', 0, 'default'),

('해수', '프리미엄 컬렉터블 피규어/키링 캐릭터. 보라(#6B4C9A) 우아한 S자 곡선 몸에 고급스러운 크리스탈 무늬, 길고 우아한 머리+분홍 리본, 별모양 귀걸이와 목걸이, 반짝이는 눈, 세련된 미소, 우아한 팔다리, 분홍 볼터치. 가슴 중앙에 분홍 육각형 소금결정 브로치.', '경쾌함, 순수함, 우아함, 신비로움', ARRAY['우아한 자유로운 영혼', '경쾌함', '순수함', '우아함', '신비로움'],
 '프리미엄 비닐/레진 3D 렌더, 보라(#6B4C9A) 우아한 S자 곡선 몸, 고급스럽게 반짝이는 크리스탈 무늬, 보라색 웨이브 머리(바다 파도 느낌)+분홍 리본 클립, 별모양 귀걸이+목걸이, 큰 검정 동그란 눈(세련된 표정), 분홍 볼터치, 연한 핑크 육각형 브로치(FFB6C1). 파도/구름/별빛 제주 배경.', '/docs/character-concept-sketches/hae-su.svg', '해수-004', 0, 'default'),

('미내', '프리미엄 컬렉터블 피규어/키링 캐릭터. 노랑(#FFD700) 동그랗고 통통한 몸에 밝은 톤과 불꽃 무늬, 노랑/주황 머리+분홍 리본, 크고 밝은 눈, 큰 웃음, 짧고 통통한 팔다리, 분홍 볼터치. 가슴 중앙에 분홍 육각형 소금결정 브로치.', '격려, 함께함, 활발함, 포용, 밝음', ARRAY['포용적인 누나', '격려', '함께함', '활발함', '포용', '밝음'],
 '프리미엄 비닐/레진 3D 렌더, 노랑(#FFD700) 동그랗고 통통한 몸, 은은한 불꽃 소용돌이 무늬, 노랑/주황 웨이브 머리(해바라기 느낌)+분홍 리본 클립, 큰 검정 동그란 눈(밝은 표정), 큰 웃음, 분홍 볼터치, 연한 핑크 육각형 브로치(FFB6C1). 파도/구름/별빛 제주 배경.', '/docs/character-concept-sketches/mi-nae.svg', '미내-005', 0, 'default'),

('현무', '프리미엄 컬렉터블 피규어/키링 캐릭터. 다크 파랑(#1F3A52) 둥근 배 모양 몸에 견고한 질감+기하학적 무늬, 짙은 회색 물결 머리(전형적 장인 스타일), 돌출된 이마(장인 정신), 차분한 갈색 눈, 안정된 미소, 짙은 회색 후드, 다크 그레이 육각형 소금결정 브로치. 짧고 굵지만 정교한 팔다리(관절 뚜렷).', '신뢰성, 기술력, 정직함, 견고함, 침착함', ARRAY['신뢰로운 형', '현무암 장인', '신뢰성', '기술력', '정직함', '견고함'],
 '프리미엄 비닐/레진 3D 렌더, 다크 파랑(#1F3A52) 둥근 몸+살짝 컴팩트, 견고한 질감+기하학적 무늬, 짙은 회색 물결 머리, 이마 주름(장인 정신 표현), 차분한 갈색 눈, 안정된 미소, 짙은 회색 후드, 다크 그레이 육각형 브로치(7FA8C9). 파도/구름/별빛 제주 배경.', '/docs/character-concept-sketches/hyeon-mu.svg', '현무-006', 0, 'default'),

('가마할방', '프리미엄 컬렉터블 피규어/키링 캐릭터. 그린/골드(#8FAE5A) 둥근 몸+뿔/귀 장식(원숭이 형상), 뾰족한 녹갈색 머리(전형적인 원숭이 스타일), 금발 머리, 돌출된 이마(장인으로서 집중), 긴 갈색/금발 턱수염, 긴 꼬리(균형과 움직임), 초록/골드 육각형 소금결정 브로치. 단숨에 점프하는 정력적 동작. 큰 갈색/검정 눈(재치 있는 미소).', '재치, 변화무쌍함, 장인 정신, 원숭이 형상, 도전적', ARRAY['재치 있는 원숭이 장인', '재치', '변화무쌍함', '장인 정신', '도전적'],
 '프리미엄 비닐/레진 3D 렌더, 그린/골드(#8FAE5A) 둥근 몸+뿔/귀 장식, 녹갈색 뾰족한 머리, 긴 갈색/금발 턱수염, 긴 꼬리(균형 움직임), 초록/골드 육각형 브로치(8FAE5A), 금발 머리, 큰 갈색/검정 눈(재치 있는 미소). 파도/구름/별빛이 반짝이는 입체감 있는 제주 테마 배경. 기존 저작권 캐릭터의 디자인/실루엣/색조합을 연상시키지 않는 완전히 독창적인 오리지널 디자인.', '/docs/character-concept-sketches/gama-hal-bang.svg', '가마할방-007', 0, 'default'),

('불이', '프리미엄 컬렉터블 피규어/키링 캐릭터. 주황/레드(#E85D3A) 둥근 몸에 불꽃 무늬, 뾰족하고 활활 타오르는 듯한 붉은 머리(불꽃 형상), 불꽃 무늬 강조된 붉은 얼굴, 큰 주황색 눈(활기찬 느낌), 활기찬 매달려 있는 동작, 주황/레드 육각형 소금결정 브로치. 따뜻하고 에너지 넘치는 정령.', '열정, 활기, 따뜻함, 용기, 에너지 넘치는 지도자', ARRAY['열정적인 불꽃 정령', '열정', '활기', '따뜻함', '용기', '에너지 넘치는 지도자'],
 '프리미엄 비닐/레진 3D 렌더, 주황/레드(#E85D3A) 둥근 몸+불꽃 무늬, 뾰족하고 활활 타오르는 붉은 머리(불꽃 형상), 붉은 얼굴(불꽃 무늬 강조), 큰 주황색 눈(활기찬 느낌), 주황/레드 육각형 브로치(E85D3A). 목 아래로 전신이 주황/레드 색상 옷/외피로 완전히 덮여 있음(얼굴 부분만 살색, 맨살 노출 금지). 파도/구름/별빛이 반짝이는 입체감 있는 제주 테마 배경.', '/docs/character-concept-sketches/bul-i.svg', '불이-008', 0, 'default')
ON CONFLICT DO NOTHING;
